import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Inscription","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/inscription.md","filePath":"en/guide/professions/inscription.md"}'),o={name:"en/guide/professions/inscription.md"};function n(s,e,l,d,c,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="inscription" tabindex="-1">Inscription <a class="header-anchor" href="#inscription" aria-label="Permalink to &quot;Inscription&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Record, preserve and carefully modify magical knowledge.</li><li>Scrolls, variants and organized grimoires offer tactical and economic roles.</li><li>Buying a casting scroll does not buy permanent knowledge; physical products remain at risk.</li></ul><p><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>What you do</th></tr></thead><tbody><tr><td>Execute the craft</td><td>Inscription <a href="/Syrolands-Public/en/guide/characters/skills.html">skill</a> supports execution; learned methods determine what can be written.</td></tr><tr><td>Specialize</td><td>Combat scrolls, variant notation, indexing and grimoire binding are candidate paths.</td></tr><tr><td>Prepare useful references</td><td>Clear notation and organized books may improve reference and preparation.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Scribes create spell scrolls and books; the craft already supports mages.</td><td>Controlled variants, notation and preservation broaden the profession’s knowledge work.</td></tr><tr><td>A written spell provides a physical casting resource.</td><td>A prepared scroll may offer faster emergency reference, at a consumable cost.</td></tr></tbody></table><p>Comparison uses familiar UO crafting loops; the official references also cover later expansions. <a href="https://uo.com/wiki/ultima-online-wiki/skills/inscription/" target="_blank" rel="noreferrer">Inscription</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A scribe could become known for reliable combat scrolls or well-indexed grimoires. A customer gains a useful reference, not automatic ownership of the scribe’s rare knowledge.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><ul><li>Known magical patterns, Magery, reagents and Alchemy may support production. Skill alone does not unlock every method.</li><li>Copying and teaching permissions, wards and rituals remain open. Workmanship grants no loot protection or flat skill bonus.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/magic/spellbooks-scrolls-and-reagents.html">Books and materials</a> · <a href="/Syrolands-Public/en/guide/magic/variants-and-glyphs.html">Spell variants</a> · <a href="/Syrolands-Public/en/guide/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Profession System</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/professions/inscription.html">Inscription</a></p>',18)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
